"""Week 4 Day 7 observable-outcome evaluation course-code tests."""

import json
import sys
from dataclasses import replace

import pytest

from .tiny_llm_base import (
    AgentError,
    EvaluationCase,
    FileExpectation,
    ReceiptExpectation,
    ReceiptStore,
    ResultExpectation,
    ToolPolicy,
    Workspace,
    evaluate_run,
    run_agent,
)


class FakeEvaluationModel:
    """Return one deterministic response per model call."""

    def __init__(self, responses):
        self.responses = iter(responses)

    def __call__(self, _messages):
        return next(self.responses)


def _completed_case(tmp_path):
    source = tmp_path / "app.py"
    source.write_text("answer = 1\n", encoding="utf-8")
    command = (
        sys.executable,
        "-c",
        (
            "from pathlib import Path; "
            "assert Path('app.py').read_text() == 'answer = 2\\n'; "
            "print('validation passed')"
        ),
    )
    approvals = []
    receipts = ReceiptStore(tmp_path / "receipts.jsonl")
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True, allowed_commands=(command,)),
        lambda action: approvals.append(action.tool) or True,
        receipts,
    )
    responses = (
        '{"tool":"read_file","path":"app.py"}',
        '{"tool":"edit_file","path":"app.py","old":"1","new":"2"}',
        json.dumps({"tool": "run_command", "argv": list(command)}),
        '{"final":"updated app.py and validated the result"}',
    )
    run = run_agent(
        "set answer = 2 in app.py and validate",
        FakeEvaluationModel(responses),
        workspace,
    )
    case = EvaluationCase(
        final_contains="validated",
        files=(FileExpectation("app.py", "answer = 2\n"),),
        results=(
            ResultExpectation("edit_file", "edited app.py"),
            ResultExpectation("run_command", "validation passed"),
        ),
        receipts=(
            ReceiptExpectation(
                "call-1", "edit_file", "ok", "edited app.py", ("app.py",)
            ),
            ReceiptExpectation("call-2", "run_command", "ok", "validation passed"),
        ),
    )
    return run, workspace, receipts, case, approvals


def test_task_1_end_to_end_run_passes_declared_observable_facts(tmp_path):
    run, workspace, receipts, case, approvals = _completed_case(tmp_path)

    report = evaluate_run(run, workspace, receipts, case)

    assert report.passed
    assert [check.name for check in report.checks] == [
        "final",
        "file:app.py",
        "result:edit_file",
        "result:run_command",
        "receipt:call-1",
        "receipt:call-2",
    ]
    assert approvals == ["edit_file", "run_command"]
    assert report.render().splitlines() == [
        "evaluation: PASS",
        "- final: PASS (required final observed)",
        "- file:app.py: PASS (content matches)",
        "- result:edit_file: PASS (required result observed)",
        "- result:run_command: PASS (required result observed)",
        "- receipt:call-1: PASS (receipt facts match)",
        "- receipt:call-2: PASS (receipt facts match)",
    ]


@pytest.mark.parametrize(
    ("fact", "failed_name"),
    [
        ("final", "final"),
        ("file", "file:app.py"),
        ("result", "result:run_command"),
        ("receipt", "receipt:call-1"),
    ],
)
def test_task_2_each_wrong_fact_fails_only_its_named_check(tmp_path, fact, failed_name):
    run, workspace, receipts, case, _approvals = _completed_case(tmp_path)
    if fact == "final":
        case = replace(case, final_contains="not in the final")
    elif fact == "file":
        case = replace(case, files=(FileExpectation("app.py", "wrong\n"),))
    elif fact == "result":
        case = replace(
            case,
            results=(
                case.results[0],
                ResultExpectation("run_command", "status: 9"),
            ),
        )
    else:
        case = replace(
            case,
            receipts=(replace(case.receipts[0], tool="write_file"), case.receipts[1]),
        )

    report = evaluate_run(run, workspace, receipts, case)

    assert not report.passed
    assert [check.name for check in report.checks if not check.passed] == [failed_name]


def test_task_3_nonessential_final_phrasing_and_event_order_are_not_graded(tmp_path):
    run, workspace, receipts, case, _approvals = _completed_case(tmp_path)
    alternate = replace(
        run,
        final="The requested outcome is validated with the recorded evidence.",
        events=tuple(reversed(run.events)),
    )

    report = evaluate_run(alternate, workspace, receipts, case)

    assert report.passed


def test_task_4_missing_unreadable_and_absent_evidence_become_failed_checks(tmp_path):
    run, workspace, _receipts, case, _approvals = _completed_case(tmp_path)
    (tmp_path / "folder").mkdir()
    unavailable = replace(
        case,
        files=(
            FileExpectation("missing.txt", "missing"),
            FileExpectation("folder", "not a file"),
        ),
    )

    report = evaluate_run(run, workspace, ReceiptStore(), unavailable)

    assert [check.name for check in report.checks if not check.passed] == [
        "file:missing.txt",
        "file:folder",
        "receipt:call-1",
        "receipt:call-2",
    ]
    assert report.render().startswith("evaluation: FAIL\n")


@pytest.mark.parametrize("tamper", ["digest", "utf8"])
def test_task_5_tampered_receipt_log_becomes_failed_checks(tmp_path, tamper):
    run, workspace, receipts, case, _approvals = _completed_case(tmp_path)
    assert receipts.path is not None
    if tamper == "digest":
        original = receipts.path.read_text(encoding="utf-8")
        receipts.path.write_text(
            original.replace('"tool": "edit_file"', '"tool": "write_file"', 1),
            encoding="utf-8",
        )
    else:
        receipts.path.write_bytes(b"\xff")

    report = evaluate_run(run, workspace, receipts, case)

    assert [check.name for check in report.checks if not check.passed] == [
        "receipt:call-1",
        "receipt:call-2",
    ]
    assert all(
        "receipt evidence unavailable" in check.detail for check in report.checks[-2:]
    )


def test_task_6_evaluation_is_pure(tmp_path):
    run, workspace, receipts, case, approvals = _completed_case(tmp_path)
    assert receipts.path is not None
    before = (
        (tmp_path / "app.py").read_bytes(),
        receipts.path.read_bytes(),
        workspace.modified_files,
        tuple(approvals),
        run,
    )

    evaluate_run(run, workspace, receipts, case)

    after = (
        (tmp_path / "app.py").read_bytes(),
        receipts.path.read_bytes(),
        workspace.modified_files,
        tuple(approvals),
        run,
    )
    assert after == before


def test_task_7_invalid_evaluation_specifications_fail_closed(tmp_path):
    with pytest.raises(ValueError, match="file path"):
        FileExpectation("../escape", "data")
    with pytest.raises(ValueError, match="result substring"):
        ResultExpectation("read_file", "  ")
    with pytest.raises(ValueError, match="receipt call id"):
        ReceiptExpectation("", "edit_file", "ok", "edited")
    with pytest.raises(ValueError, match="exit_state"):
        ReceiptExpectation("call-1", "edit_file", "maybe", "edited")
    with pytest.raises(ValueError, match="file paths must be unique"):
        EvaluationCase(
            "done",
            files=(FileExpectation("a/b", "1"), FileExpectation("a//b", "2")),
        )
    with pytest.raises(ValueError, match="receipt call ids must be unique"):
        EvaluationCase(
            "done",
            receipts=(
                ReceiptExpectation("call-1", "edit_file", "ok", "edited"),
                ReceiptExpectation("call-1", "run_command", "ok", "status"),
            ),
        )

    run, workspace, receipts, _case, _approvals = _completed_case(tmp_path)
    with pytest.raises(ValueError, match="EvaluationCase"):
        evaluate_run(run, workspace, receipts, object())
    with pytest.raises(ValueError, match="AgentRun"):
        evaluate_run(object(), workspace, receipts, EvaluationCase("done"))


def test_task_7_receipt_lookup_errors_become_failed_checks(tmp_path, monkeypatch):
    run, workspace, receipts, case, _approvals = _completed_case(tmp_path)
    in_memory = ReceiptStore()
    monkeypatch.setattr(
        in_memory,
        "get",
        lambda _call_id: (_ for _ in ()).throw(AgentError("lookup broke")),
    )

    report = evaluate_run(run, workspace, in_memory, case)

    assert [check.name for check in report.checks if not check.passed] == [
        "receipt:call-1",
        "receipt:call-2",
    ]
    assert all("receipt lookup failed" in check.detail for check in report.checks[-2:])
